const body = $json.body ?? $json;

const lead = {
  name: String(body.name ?? '').trim(),
  email: String(body.email ?? '').trim().toLowerCase(),
  company: String(body.company ?? '').trim(),
  jobTitle: String(body.jobTitle ?? '').trim(),
  website: String(body.website ?? '').trim(),
  industry: String(body.industry ?? '').trim(),
  companySize: Number(body.companySize ?? 0),
  message: String(body.message ?? '').trim(),
  source: String(body.source ?? 'website').trim(),
  receivedAt: new Date().toISOString()
};

const errors = [];
if (!lead.name) errors.push('Name is required');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(lead.email)) errors.push('A valid email is required');

return [{
  json: {
    ...lead,
    valid: errors.length === 0,
    validationErrors: errors
  }
}];

const lead = $json;

// Demo duplicate check.
// Replace this node with a real CRM/Google Sheets/database lookup in production.
const duplicate = false;

return [{
  json: {
    ...lead,
    duplicate
  }
}];

const lead = $json;

let score = 0;

if (lead.email) score += 10;
if (lead.company) score += 15;
if (lead.jobTitle) score += 15;
if (lead.website) score += 10;
if (lead.industry) score += 10;
if (lead.message.length >= 30) score += 15;
if (lead.companySize >= 50) score += 15;
if (lead.companySize >= 200) score += 10;

let priority = 'Low';
let route = 'Nurture';

if (score >= 70) {
  priority = 'High';
  route = 'Sales';
} else if (score >= 45) {
  priority = 'Medium';
  route = 'SDR';
}

return [{
  json: {
    ...lead,
    leadScore: score,
    priority,
    route,
    status: 'Qualified',
    aiTask: `Create a concise, personalized sales message for ${lead.name} at ${lead.company}. Their role is ${lead.jobTitle}. Industry: ${lead.industry}. Their message is: ${lead.message}`
  }
}];

const lead = $json;

return [{
  json: {
    ...lead,
    crmRecord: {
      name: lead.name,
      email: lead.email,
      company: lead.company,
      jobTitle: lead.jobTitle,
      website: lead.website,
      industry: lead.industry,
      companySize: lead.companySize,
      source: lead.source,
      score: lead.leadScore,
      priority: lead.priority,
      route: lead.route,
      status: lead.status,
      createdAt: lead.receivedAt
    }
  }
}];

const lead = $json;

return [{
  json: {
    ...lead,
    salesNotification: `HIGH PRIORITY LEAD: ${lead.name} | ${lead.company} | Score: ${lead.leadScore}`,
    nextAction: 'Immediate sales follow-up',
    followUpType: 'Personalized outreach'
  }
}];

const lead = $json;

return [{
  json: {
    ...lead,
    salesNotification: `LEAD: ${lead.name} | ${lead.company} | Score: ${lead.leadScore} | Priority: ${lead.priority}`,
    nextAction: lead.priority === 'Medium'
      ? 'SDR follow-up within 24 hours'
      : 'Add to nurture sequence',
    followUpType: lead.priority === 'Medium'
      ? 'SDR follow-up'
      : 'Automated nurture'
  }
}];

const lead = $json;

return [{
  json: {
    success: true,
    processedAt: new Date().toISOString(),
    lead: {
      name: lead.name,
      email: lead.email,
      company: lead.company
    },
    qualification: {
      score: lead.leadScore,
      priority: lead.priority,
      route: lead.route
    },
    nextAction: lead.nextAction,
    message: 'Lead processed successfully'
  }
}];

return [{
  json: {
    success: false,
    message: 'Lead validation failed',
    errors: $json.validationErrors ?? ['Invalid lead data']
  }
}];

return [{
  json: {
    success: true,
    duplicate: true,
    message: 'Lead already exists. No duplicate processing was performed.',
    email: $json.email
  }
}];
